import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    if n <= 1:
        return

    scores = list(map(int, data[1:n+1]))
    num_partnerships = n - 1

    contribution = []
    for i in range(n):
        if i == 0:
            count = 1
        elif i == n - 1:
            count = n - 1
        else:
            count = 1 + (n - 1 - i)
        contribution.append(scores[i] / count)

    partnerships = []
    for p in range(num_partnerships):
        total = contribution[p]
        total += contribution[p + 1]
        partnerships.append(int(total))

    print(' '.join(map(str, partnerships)))

if __name__ == "__main__":
    main()
